96	const resourceCompanyItems: FlyoutItem[] = [
97	  { label: "About", description: "Our mission and team", href: "/about", icon: <SparklesIcon className="size-4" /> },
98	  { label: "How We Work", description: "Our culture and values", href: "https://notion.warp.dev/", icon: <BookOpenIcon className="size-4" /> },
99	  { label: "Careers", description: "Join the team at Warp", href: "/careers", icon: <BriefcaseIcon className="size-4" /> },
100	  { label: "Press", description: "Media coverage and press kit", href: "/press", icon: <NewspaperIcon className="size-4" /> },
101	  { label: "Research", description: "Reports and insights", href: "/research", icon: <FileTextIcon className="size-4" /> },
