110	function FlyoutItemRow({ item, hoverOnWrapper }: { item: FlyoutItem; hoverOnWrapper?: boolean }) {
111	  const external = !!item.external;
112	  const anchor = (
113	    <a
114	      href={item.href}
115	      target={external ? "_blank" : undefined}
116	      rel={external ? "noopener noreferrer" : undefined}
117	      className={
118	        hoverOnWrapper
119	          ? "flex items-start gap-3 rounded-lg p-3 focus:outline-none focus-visible:ring-2 focus-visible:ring-(--color-text)"
120	          : "group flex items-start gap-3 rounded-lg p-3 hover:bg-(--color-text)/5 focus:outline-none focus-visible:ring-2 focus-visible:ring-(--color-text)"
121	      }
122	    >
123	      <span className="mt-0.5 inline-flex size-6 shrink-0 items-center justify-center rounded-md bg-(--color-text)/5 text-(--color-text-secondary) ring-1 ring-inset ring-(--color-border)">
