139	}
140	
141	function FlyoutItemProduct({ item }: { item: FlyoutItem }) {
142	  return (
143	    <a
144	      href={item.href}
145	      className="group flex items-start gap-3 rounded-lg p-3 hover:bg-(--color-text)/5"
146	    >
