148	        {item.icon}
149	      </span>
150	      <div>
151	        <p className="inline-flex items-center gap-1 text-sm font-semibold text-(--color-text)">{item.label}</p>
152	        <p className="mt-0.5 text-sm text-(--color-muted)">{item.description}</p>
153	      </div>
154	    </a>
155	  );
156	}
157	
158	function TwoColumnFlyout({ columns }: { columns: { title: string; items: FlyoutItem[] }[] }) {
159	  return (
160	    <div className="flex divide-x divide-(--color-border) p-2 *:flex-1 [&>*:first-child]:pr-4 [&>*:not(:first-child)]:pl-4">
161	      {columns.map(col => (
162	        <div key={col.title} className="min-w-44">
163	          <div className="mb-1 flex items-center justify-between gap-2 px-3 py-1">
164	            <span className="font-mono text-xs font-medium uppercase tracking-wider text-(--color-muted)">{col.title}</span>
165	          </div>
166	          <div className="flex flex-col">
167	            {col.items.map(item => (
168	              <FlyoutItemRow key={item.label} item={item} hoverOnWrapper />
169	            ))}
170	          </div>
171	        </div>
172	      ))}
173	    </div>
174	  );
175	}
176	
177	// Run before paint on the client (avoids a position flash) but fall back to a
178	// plain effect during SSR so React doesn't warn about useLayoutEffect.
179	const useIsomorphicLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;
180	
181	
182	const flyoutPanelBase = "navbar-flyout fixed left-6 top-[calc(var(--scroll-padding-top)-0.75rem)] z-[9999] origin-top-left rounded-[calc(var(--radius)*3)] bg-(--color-background) p-2 shadow-lg ring-1 ring-(--color-border)";
183	const flyoutSmallWidth = "w-max max-w-[calc(100vw-3rem)] lg:max-w-2xl";
184	const flyoutWideWidth = "w-[calc(100vw-3rem)] max-w-3xl";
185	
186	type ActiveFlyout = "products" | "solutions" | "resources" | "enterprise" | null;
187	
188	export default function Navbar() {
189	  const [activeFlyout, setActiveFlyout] = useState<ActiveFlyout>(null);
190	  const [mobileOpen, setMobileOpen] = useState(false);
191	  const navRef = useRef<HTMLDivElement>(null);
192	  const leaveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
193	
194	  useEffect(() => {
195	    function handleClickOutside(e: MouseEvent) {
196	      if (!navRef.current?.contains(e.target as Node)) {
197	        setActiveFlyout(null);
198	      }
199	    }
200	    document.addEventListener("mousedown", handleClickOutside);
201	    return () => document.removeEventListener("mousedown", handleClickOutside);
202	  }, []);
203	
204	  useEffect(() => {
205	    document.body.classList.toggle("overflow-hidden", mobileOpen);
206	    return () => { document.body.classList.remove("overflow-hidden"); };
207	  }, [mobileOpen]);
208	
209	  useEffect(() => {
210	    const onKey = (e: KeyboardEvent) => {
211	      if (e.key !== "d" && e.key !== "D") return;
212	      if (e.metaKey || e.ctrlKey || e.altKey) return;
213	      const target = e.target as HTMLElement | null;
214	      if (target?.closest("input, textarea, select, [contenteditable='true']")) return;
215	      e.preventDefault();
216	      window.open(
217	        "/",
218	        "_blank",
219	        "noopener,noreferrer"
220	      );
221	    };
222	    document.addEventListener("keydown", onKey);
223	    return () => document.removeEventListener("keydown", onKey);
224	  }, []);
225	
226	  const cancelLeave = useCallback(() => {
227	    if (leaveTimerRef.current) clearTimeout(leaveTimerRef.current);
228	  }, []);
229	
230	  const scheduleLeave = useCallback(() => {
231	    leaveTimerRef.current = setTimeout(() => setActiveFlyout(null), 200);
232	  }, []);
233	
234	  const openFlyout = useCallback((name: ActiveFlyout) => {
235	    cancelLeave();
236	    setActiveFlyout(name);
237	  }, [cancelLeave]);
238	
239	  const toggleFlyout = (name: ActiveFlyout) => {
240	    setActiveFlyout(prev => prev === name ? null : name);
241	  };
242	
243	  // Position the open flyout like the real site: anchored to its trigger button,
244	  // but clamped so it never overflows the 1.5rem viewport gutter on either side.
245	  // left = clamp(gutter, buttonLeft, viewportWidth - gutter - panelWidth)
246	  useIsomorphicLayoutEffect(() => {
247	    if (!activeFlyout) return;
248	    const nav = navRef.current;
249	    if (!nav) return;
250	    const panel = nav.querySelector<HTMLElement>(`[data-flyout-panel="${activeFlyout}"]`);
251	    const trigger = nav.querySelector<HTMLElement>(`[data-flyout-trigger="${activeFlyout}"]`);
252	    if (!panel || !trigger) return;
253	
254	    const position = () => {
255	      const gutter = 24; // 1.5rem
256	      const btn = trigger.getBoundingClientRect();
257	      const width = panel.offsetWidth;
258	      const maxLeft = window.innerWidth - gutter - width;
259	      const left = Math.max(gutter, Math.min(btn.left, maxLeft));
260	      // The sticky <header>'s backdrop-filter makes this fixed panel positioned
261	      // relative to the header, not the viewport. Rather than guess which ancestor
262	      // is the containing block, measure it: park the panel at 0,0 and read where
263	      // that lands, then offset our viewport-space targets by that origin.
264	      panel.style.left = "0px";
265	      panel.style.top = "0px";
266	      const origin = panel.getBoundingClientRect();
267	      panel.style.left = `${left - origin.left}px`;
268	      panel.style.top = `${btn.bottom + 11 - origin.top}px`;
269	    };
270	
271	    position();
272	    window.addEventListener("resize", position);
273	    return () => window.removeEventListener("resize", position);
274	  }, [activeFlyout]);
275	
276	  return (
277	    <header className="sticky top-0 z-10 bg-background/70 backdrop-blur-md supports-backdrop-filter:bg-background/60">
278	      <nav ref={navRef}>
279	        <div className="mx-auto flex h-(--scroll-padding-top) max-w-7xl items-center gap-4 px-6 lg:px-10">
280	          <div className="flex flex-1 items-center gap-12">
281	            <div className="flex items-center">
282	              <Link href="/" className="inline-flex items-stretch">
283	                <WarpLogoFull className="hidden h-5 w-auto lg:block" />
284	                <WarpMark className="h-6 w-auto lg:hidden" />
285	              </Link>
286	            </div>
287	
288	            {/* Desktop nav — items-stretch so each wrapper fills the full nav height */}
