    logoWidth: 123,
    logoHeight: 33,
    bg: "/images/partner-openai-bg.jpg",
    badge: "Livestream",
    badgeUrl: "https://www.youtube.com/watch?v=Kw6bfR5oLuQ",
  },
  {
    name: "Docker",
    logo: "/logos/docker.svg",
    logoWidth: 130,
    logoHeight: 30,
