"use client";

import { useState, useEffect, useCallback, type CSSProperties } from "react";
import Image from "next/image";

interface Tab {
  label: string;
  description: string;
  image: { src: string; alt: string; width: number; height: number };
}

interface Props {
  tabs: Tab[];
  autoAdvanceMs?: number;
}

interface BodyProps {
  tabs: Tab[];
  activeIndex: number;
  progressKey: number;
  autoAdvanceMs: number;
  onSelect: (i: number) => void;
}

function CarouselBody({
  tabs,
  activeIndex,
  progressKey,
  autoAdvanceMs,
  onSelect,
}: BodyProps) {
  return (
    <>
      <div className="flex scrollbar-none flex-row overflow-x-auto border-b border-(--color-border)/40 mask-[linear-gradient(to_right,black_calc(100%-3rem),transparent)] sm:mask-none">
        {tabs.map((tab, i) => {
          const isActive = i === activeIndex;
          return (
            <div
              key={tab.label}
              className={`flex-1 ${i > 0 ? "border-l border-(--color-border)/40" : ""}`}
            >
              <div
                role="button"
                tabIndex={0}
                onClick={() => onSelect(i)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    onSelect(i);
                  }
                }}
                className={`group/tab flex w-full min-w-40 cursor-pointer flex-col text-left transition-colors ${
                  isActive
                    ? "bg-text/5"
                    : "hover:bg-text/2"
                }`}
              >
                <div>
                  <div className="h-px w-full overflow-hidden bg-(--color-text)/10">
                    {isActive ? (
                      <div
                        key={progressKey}
                        className="h-full bg-(--color-tertiary) animate-[fill-progress_var(--fp-duration)_linear_forwards]"
                        style={{ "--fp-duration": `${autoAdvanceMs}ms` } as CSSProperties}
                      />
                    ) : (
                      <div className="h-full w-0 bg-(--color-tertiary) transition-[width] duration-300" />
                    )}
                  </div>
                  <div className="px-4 py-3">
                    <span
                      className={`text-sm/5 tracking-tight transition-colors ${
                        isActive
                          ? "text-(--color-text)"
                          : "text-(--color-muted) group-hover/tab:text-(--color-text-secondary)"
                      }`}
                    >
                      {tab.label}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div className="relative aspect-16/10 w-full overflow-hidden rounded-(--img-radius)">
        {tabs.map((tab, i) => {
          const isActive = i === activeIndex;
          return (
            <div
              key={tab.label}
              aria-hidden={!isActive}
              className={`absolute inset-0 transition-opacity duration-400 *:h-full *:w-full ${
                isActive ? "z-10 opacity-100" : "z-0 opacity-0"
              }`}
            >
              <div
                data-color="light"
                data-placement="center"
                className="relative overflow-hidden bg-(--color-panel)"
              >
                <div className="pointer-events-none relative z-20 h-full [&_img]:pointer-events-auto">
                  <div className="relative flex h-full items-center justify-center">
                    <div className="h-full w-full *:relative *:h-full *:w-full *:object-cover">
                      <Image
                        src={tab.image.src}
                        alt={tab.image.alt}
                        fill
                        className="object-cover"
                        sizes="(max-width: 1024px) 100vw, 80vw"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
        <span className="absolute right-3 top-3 z-20 rounded-full bg-background/70 px-2.5 py-1 text-xs font-medium text-(--color-text) backdrop-blur-sm">
          {activeIndex + 1}/{tabs.length}
        </span>
      </div>
    </>
  );
}

export default function TerminalFeatureCarousel({
  tabs,
  autoAdvanceMs = 6000,
}: Props) {
  const [activeIndex, setActiveIndex] = useState(0);
  const [progressKey, setProgressKey] = useState(0);

  const advance = useCallback(() => {
    setActiveIndex((i) => (i + 1) % tabs.length);
    setProgressKey((k) => k + 1);
  }, [tabs.length]);

  useEffect(() => {
    const t = setTimeout(advance, autoAdvanceMs);
    return () => clearTimeout(t);
  }, [activeIndex, advance, autoAdvanceMs]);

  const selectTab = (i: number) => {
    setActiveIndex(i);
    setProgressKey((k) => k + 1);
  };

  return (
    <section
      data-component="FeatureCarousel"
      data-motion-reveal="visible"
      className="py-16"
    >
      <div
        data-component="Container"
        className="mx-auto flex w-full max-w-(--content-max-width) flex-col gap-10 px-6 sm:gap-16 lg:px-10"
      >
        <div
          aria-hidden="true"
          className="pointer-events-none invisible absolute -left-[9999px]"
        >
          {tabs.map((tab) => (
            <div key={tab.label}>
              <div
                data-component="Text"
                className="text-(--color-text-secondary) text-sm/7 [font-family:var(--font-body)] [font-weight:var(--body-weight)] text-(length:--body-size) leading-(--body-line-height)"
              >
                <p>{tab.description}</p>
              </div>
            </div>
          ))}
        </div>

        <div
          data-motion-reveal-item=""
          className="overflow-hidden rounded-lg bg-(--color-background) [--reveal-delay:0ms] lg:hidden"
        >
          <CarouselBody
            tabs={tabs}
            activeIndex={activeIndex}
            progressKey={progressKey}
            autoAdvanceMs={autoAdvanceMs}
            onSelect={selectTab}
          />
        </div>

        <div
          data-motion-reveal-item=""
          className="hidden overflow-hidden rounded-lg bg-(--color-background) [--reveal-delay:80ms] lg:flex lg:flex-col"
        >
          <CarouselBody
            tabs={tabs}
            activeIndex={activeIndex}
            progressKey={progressKey}
            autoAdvanceMs={autoAdvanceMs}
            onSelect={selectTab}
          />
        </div>
      </div>
    </section>
  );
}

import LockIcon from "@/components/icons/LockIcon";
import ShieldIcon from "@/components/icons/ShieldIcon";
import EyeSlashIcon from "@/components/icons/EyeSlashIcon";
import GlobeIcon from "@/components/icons/GlobeIcon";
import SlidersIcon from "@/components/icons/SlidersIcon";
import KeyIcon from "@/components/icons/KeyIcon";

const features: {
  icon: React.ReactNode | null;
  title: string;
  description: string;
}[] = [
  {
    icon: <LockIcon />,
    title: "Enterprise-Grade controls.",
    description:
      "SAML-based SSO, role based access control for permission management",
  },
  {
    icon: <ShieldIcon />,
    title: "Your data, your control.",
    description:
      "SOC2 Type 2 compliance; industry leading data policies including zero-data retention",
  },
  {
    icon: <EyeSlashIcon />,
    title: "Privacy, even from agents.",
    description: "Secret redaction with custom regexes",
  },
  {
    icon: <GlobeIcon />,
    title: "Flexible hosting and compute.",
    description:
      "BYOLLM support and flexible hosting so your code stays inside your infrastructure",
  },
  {
    icon: <SlidersIcon />,
    title: "Centralized admin controls.",
    description:
      "Set agent permissions for your whole team; central usage reporting",
  },
  {
    icon: <KeyIcon />,
    title: "Password manager integrations.",
    description: "Read secrets directly from 1Password or LastPass",
  },
];

export default function TerminalFeatureList() {
  return (
    <section
      data-component="Section"
      id="terminal-features"
      data-motion-reveal="visible"
      className="py-16"
    >
      <div
        data-component="Container"
        className="mx-auto flex w-full max-w-(--content-max-width) flex-col gap-10 px-6 sm:gap-16 lg:px-10"
      >
        {/* pb-6 reproduces the original's empty body-copy spacing slot (one gap-6 step) below the heading without an empty text container */}
        <div
          data-motion-reveal-item=""
          className="flex max-w-2xl flex-col gap-6 pb-6 [--reveal-delay:0ms]"
        >
          <div className="flex flex-col gap-2">
            <div className="font-mono text-xs/7 font-medium uppercase tracking-widest text-(--color-text-secondary)">
              Features
            </div>
            <h2
              data-component="Subheading"
              className="text-pretty text-(--color-text) [font-family:var(--font-heading)] [font-weight:var(--heading-weight)] text-[clamp(1.75rem,3.5vw,calc(var(--heading-size)*0.7))] leading-[1.15] [letter-spacing:var(--heading-letter-spacing)]"
            >
              Designed for security. Built for organizations.
            </h2>
          </div>
        </div>

        <div
          data-motion-reveal-item=""
          className="[--reveal-delay:80ms]"
        >
          <div className="grid grid-cols-1 gap-10 sm:grid-cols-2 lg:grid-cols-3">
            {features.map((feature) => (
              <div
                key={feature.title}
                data-component="Feature"
                className="flex flex-col gap-4 text-base/7"
              >
                {feature.icon ? (
                  <div className="flex size-6 items-center justify-start text-(--color-text) [&_svg]:size-full">
                    {feature.icon}
                  </div>
                ) : (
                  <div aria-hidden="true" className="h-6" />
                )}
                <div className="text-(--color-text-secondary) [&_p]:m-0 [&_p]:inline">
                  <h3 className="inline font-semibold text-(--color-text)">
                    {feature.title}
                  </h3>{" "}
                  <p>{feature.description}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
